'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = n => Number(n||0).toLocaleString('en-US');
const idr = n => new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n||0);
const signed = n => (n>0?'+':'')+idr(n);
const safeGet = (store,key) => {try{return store.getItem(key);}catch{return null;}};
const safeSet = (store,key,value) => {try{value===null?store.removeItem(key):store.setItem(key,value);}catch{}};
const parse = value => {try{return JSON.parse(value);}catch{return null;}};
let S=null, ws=null, connected=false, pending=false, reconnectTimer, reconnectAttempt=0, toastTimer, replaced=false;
let session=parse(safeGet(sessionStorage,'mejakita.poker.seat'))||window.MejaRoom.saved('poker'), saved=parse(safeGet(localStorage,'mejakita.poker.last-seat'));
let info={addresses:[]}, settingsDraft=null, guideStep=0, beginner=safeGet(localStorage,'mejakita.poker.beginner')!=='false';
let enteredName=window.MejaRoom.name(safeGet(localStorage,'mejakita.poker.name')||''), enteredCode=new URLSearchParams(location.search).get('room')||'';
let modalType=null, selectedAddress=null, lastScreen=null, settingsTimer;
// The shared theme preference is applied in the head by /theme.js.
const SUITS={s:'♠',h:'♥',d:'♦',c:'♣'};
const suitNames={s:'spades',h:'hearts',d:'diamonds',c:'clubs'};
const rankLabel=r=>({11:'J',12:'Q',13:'K',14:'A'}[r]||r);
function card(c,extra='') {
  if(c==='blank')return '<span class="playing-card blank" aria-label="Card not dealt"><span class="suit">·</span></span>';
  if(!c)return '<span class="playing-card back" aria-label="Hidden card"></span>';
  const corner=`${rankLabel(c.r)}<span>${SUITS[c.s]}</span>`;
  return `<span class="playing-card ${['h','d'].includes(c.s)?'red':''} ${extra}" role="img" aria-label="${rankLabel(c.r)} of ${suitNames[c.s]}"><span class="corner">${corner}</span><span class="suit">${SUITS[c.s]}</span><span class="corner bottom" aria-hidden="true">${corner}</span></span>`;
}
function cards(cs,cls='',best=[]) {return `<div class="cards ${cls}">${cs.map(c=>card(c,c&&best.some(b=>b.r===c.r&&b.s===c.s)?'best':'')).join('')}</div>`;}
function cs(text){return text.split(' ').map(c=>({r:'23456789TJQKA'.indexOf(c[0])+2,s:c[1]}));}
function toast(message){$('#toast').textContent=message;$('#toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),5000);}
function connectionStatus(){const el=$('#connection');el.classList.toggle('hidden',connected);el.textContent=S?'Connection lost. Reconnecting to your seat… Offline turns check or fold after 15 seconds.':'Connecting to your poker table…';}
function send(message){if(!window.MejaRoom.outgoing(message))return false;if(!connected){toast('Waiting for the server connection.');return false;}if(pending)return false;pending=true;ws.send(JSON.stringify(message));setTimeout(()=>{if(pending){pending=false;render();}},4000);return true;}
function connect(){
  clearTimeout(reconnectTimer);ws=new WebSocket(`${location.protocol==='https:'?'wss:':'ws:'}//${location.host}/poker/ws`);
  ws.onopen=()=>{connected=true;pending=false;reconnectAttempt=0;connectionStatus();render();window.MejaRoom.connected(session,send,target=>{enteredCode=target;render();});};
  ws.onmessage=event=>{
    const msg=JSON.parse(event.data);
    if(msg.type==='hello')return;
    pending=false;
    if(window.MejaRoom.receive(msg,send))return;
    if(msg.type==='joined'){session={code:msg.code,token:msg.token,id:msg.id};saved=session;safeSet(sessionStorage,'mejakita.poker.seat',JSON.stringify(session));safeSet(localStorage,'mejakita.poker.last-seat',JSON.stringify(session));settingsDraft=null;history.replaceState(null,'',`/poker/?room=${msg.code}`);}
    else if(msg.type==='state'){const previous=S;S=msg;if(settingsDraft&&JSON.stringify(settingsDraft)===JSON.stringify(Object.fromEntries(Object.keys(settingsDraft).map(k=>[k,S.settings[k]]))))settingsDraft=null;render();if(previous?.phase!=='ended'&&S.phase==='ended')closeModal();if(modalType==='balances')showBalances();}
    else if(msg.type==='error'){toast(msg.message);if(msg.sessionUnavailable){session=null;safeSet(sessionStorage,'mejakita.poker.seat',null);if(saved?.code===msg.code||!msg.code){saved=null;safeSet(localStorage,'mejakita.poker.last-seat',null);}}render();}
    else if(msg.type==='left'){if(msg.dissolved){saved=null;safeSet(localStorage,'mejakita.poker.last-seat',null);}S=null;session=null;safeSet(sessionStorage,'mejakita.poker.seat',null);settingsDraft=null;closeModal();history.replaceState(null,'','/poker/');render();}
    else if(msg.type==='replaced'){replaced=true;session=null;S=null;safeSet(sessionStorage,'mejakita.poker.seat',null);toast('Your seat was opened in another tab.');render();}
  };
  ws.onclose=()=>{window.MejaRoom.disconnected();connected=false;pending=false;connectionStatus();render();if(!replaced)reconnectTimer=setTimeout(connect,Math.min(1000*2**reconnectAttempt++,8000));};
  ws.onerror=()=>{};
}
function currentPlayer(){return S?.players.find(p=>p.id===S.you)||(S?.spectator?{name:'Penonton',hole:[],stack:0,totalBuyIn:0,contributed:0,inHand:false,folded:false}:null);}
function isHost(){return S?.hostId===S?.you;}
function button(label,action,cls='',attrs=''){return `<button class="btn ${cls}" data-do="${action}" ${pending?'disabled':''} ${attrs}>${label}</button>`;}
function defaultShareOrigin(){return !['localhost','127.0.0.1','[::1]'].includes(location.hostname)?location.origin:(selectedAddress||info.addresses[0]||location.origin);}
function shareLink(){return `${defaultShareOrigin()}/poker/?room=${S.code}`;}
function render(){
  const active=document.activeElement;const focus=active&&$('#app').contains(active)&&active.id?{id:active.id,start:active.selectionStart,end:active.selectionEnd}:null;
  $('#app').innerHTML=!S?landing():S.phase==='lobby'?lobby():S.phase==='ended'?ended():game();
  if(S&&(S.phase==='lobby'||S.phase==='ended')){$('#app').innerHTML='<div class="mk-layout"><div>'+$('#app').innerHTML+'</div>'+tableSidebar()+'</div>';}
  if(focus){const el=document.getElementById(focus.id);if(el){el.focus({preventScroll:true});try{el.setSelectionRange(focus.start,focus.end);}catch{}}}
  const screen=S?.phase||'landing';if(screen!==lastScreen){window.scrollTo(0,0);lastScreen=screen;}
  document.title=S?`${S.code} · Poker P2P`:'Poker P2P · A table for everyone';
}
function landing(){return `<section class="landing"><div class="welcome-grid"><div class="welcome-copy"><div class="eyebrow">Texas Hold’em, together</div><h1>Good company.<br>A little <em>poker.</em></h1><p>Your own table for game night. Join your friends, learn as you play, and keep every chip accounted for.</p><div class="panel entry-card"><form id="create-form"><label class="field" for="player-name">YOUR NAME<input id="player-name" name="name" maxlength="24" autocomplete="nickname" placeholder="What should we call you?" value="${esc(enteredName)}" required></label>${button('Create a room <span>↗</span>','create','primary full arrow',connected?'':'disabled')}</form><div class="divider"></div><form id="join-form" class="join-row"><label class="field" for="join-code">HAVE A ROOM CODE?<input id="join-code" name="code" class="code-input" maxlength="4" placeholder="ABCD" value="${esc(enteredCode)}" autocomplete="off" autocapitalize="characters" required></label>${button('Join room','join','',connected?'':'disabled')}</form><div class="entry-foot"><i class="online-dot"></i> No accounts. Just a room link.</div>${saved?`<div class="divider"></div>${button(`Return to saved room ${esc(saved.code)} →`,'resume','ghost full small')}`:''}</div></div><div class="welcome-art"><div class="art-head"><span class="serif">Pull up a chair.</span><span class="pill">2–8 players</span></div><div class="sample-table" aria-label="Green felt poker table with an ace and king of spades"><div class="table-wordmark">♣ &nbsp; THE HOME TABLE &nbsp; ♠</div><div class="sample-hand">${card({r:14,s:'s'})}${card({r:13,s:'s'})}</div><div class="sample-chips"><span class="chip">100</span><span class="chip red">25</span></div><div class="sample-note">A table for everyone</div></div><div class="floating-note"><span>♧</span><div><strong>First time? You’re in good hands.</strong><p>A step-by-step guide, hand rankings, and helpful prompts are always one tap away.</p></div></div></div></div><div class="feature-strip"><div class="feature"><span class="feature-number">01</span><div><h3>A room of your own</h3><p>Create a table, share four letters, and bring your friends together.</p></div></div><div class="feature"><span class="feature-number">02</span><div><h3>Learn at your own pace</h3><p>No turn timer for connected players. Take a moment, check the guide.</p></div></div><div class="feature"><span class="feature-number">03</span><div><h3>Every chip, crystal clear</h3><p>Set a chip’s IDR value. Track buy-ins and see who pays whom at the end.</p></div></div></div></section>`;}
function playModeCopy(s){return 'Settings lock when the first hand starts. '+(s.playMode==='quick'?'Quick Play: one hand, then automatic final recap. No minimum dealer rotations.':'Minimum play: 3 dealer rotations per player. Early finish is allowed if only one player has chips and all others decline a rebuy.');}
function settingsForm(){const s=settingsDraft||S.settings;return `<form id="settings-form" class="stack"><div class="fields"><label class="field">Durasi permainan<select id="play-mode" name="playMode">${[['standard','Santai · 3 putaran dealer'],['quick','Quick Play · 1 tangan']].map(([value,label])=>`<option value="${value}" ${(s.playMode||'standard')===value?'selected':''}>${label}</option>`).join('')}</select><small>Quick Play selesai otomatis setelah satu tangan.</small></label><label class="field">1 chip in IDR<input id="chip-value" name="chipValue" type="number" min="0" max="1000000" step="1" value="${s.chipValue}"><small>0 = practice, no payments</small></label><label class="field">Practice bots<select id="bot-count" name="bots">${[0,1,2,3,4,5,6,7].map(n=>`<option value="${n}" ${n===s.bots?'selected':''}>${n?n+' bot'+(n>1?'s':''):'No bots'}</option>`).join('')}</select></label><label class="field">Bot difficulty<select id="bot-level" name="botLevel">${[['easy','Easy'],['normal','Normal'],['hard','Hard']].map(([value,label])=>`<option value="${value}" ${s.botLevel===value?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="notice"><b>Pengaturan meja saat ini</b><p>${num(s.buyIn)} chip per buy-in · blind ${s.smallBlind}/${s.bigBlind} · ${s.maxPlayers} kursi. Bisa langsung dipakai, atau sesuaikan di Customize.</p></div>${MejaRoom.customize('poker-table','Customize · chip, blind, dan kursi',`<div class="fields"><label class="field">Chips per buy-in<input id="buy-in" name="buyIn" type="number" min="20" max="1000000" step="1" value="${s.buyIn}"><small>At least 20 big blinds</small></label><label class="field">Small blind<input id="small-blind" name="smallBlind" type="number" min="1" max="50000" value="${s.smallBlind}"></label><label class="field">Big blind<input id="big-blind" name="bigBlind" type="number" min="2" max="100000" value="${s.bigBlind}"></label><label class="field">Table seats<select id="max-players" name="maxPlayers">${[2,3,4,5,6,7,8].map(n=>`<option value="${n}" ${n===s.maxPlayers?'selected':''}>${n} players</option>`).join('')}</select></label></div><label class="check-label"><input id="allow-rebuy" name="allowRebuy" type="checkbox" ${s.allowRebuy?'checked':''}> Allow rebuys, approved by the host</label>`)}<div class="notice"><div class="eyebrow">Each buy-in</div><div class="settings-cost" id="settings-cost">${idr(s.buyIn*s.chipValue)}</div><span id="practice-note">${num(s.buyIn)} chips × ${idr(s.chipValue)} · nilai simulasi</span></div><p class="small muted">Settings save automatically. Starting uses the values shown here.</p><p class="small muted" id="play-mode-note">${playModeCopy(s)}</p></form>`;}

function lobby(){const s=S.settings;return `<section class="room-page"><div class="page-heading"><div><div class="eyebrow">Make yourself at home</div><h1>The waiting room.</h1><p>${isHost()?'You’re the host. Set the table, then deal everyone in.':'Take a seat. Your host will start when everyone is ready.'}</p></div>${button('Leave room','leave','ghost small')}</div><div class="lobby-grid"><div class="stack"><section class="panel"><div class="panel-title"><h2>Invite your friends</h2><span class="pill">${S.players.length+s.bots} / ${s.maxPlayers} seats</span></div><div class="small muted">Open the invite link, then enter this code.</div><div class="room-code">${esc(S.code)}</div><div class="row"><div class="grow">${button('Copy room code','copy-code','full')}</div><div class="grow">${button('Copy invite link ↗','copy-link','primary full')}</div></div><div class="address-list">Friends open: <strong>${esc(defaultShareOrigin())}</strong>${info.addresses.length>1?`<label class="field small">Network address<select id="share-address">${info.addresses.map(a=>`<option ${a===defaultShareOrigin()?'selected':''}>${esc(a)}</option>`).join('')}</select></label>`:''}</div></section><section class="panel"><div class="panel-title"><h2>Table settings</h2><span class="small muted">${isHost()?'Host controls':'Set by host'}</span></div>${isHost()?settingsForm():`<div class="stack"><p class="small">1 chip = <strong>${idr(s.chipValue)}</strong></p><p class="small">Buy-in: <strong>${num(s.buyIn)} chips · ${idr(s.buyIn*s.chipValue)}</strong></p><p class="small">Blinds: <strong>${s.smallBlind} / ${s.bigBlind}</strong></p><p class="small">Rebuys: <strong>${s.allowRebuy?'Host approval':'Disabled'}</strong></p><p class="notice">${s.playMode==='quick'?'Quick Play · one hand, then automatic final recap.':'Minimum play: 3 dealer rotations per player. The host confirms when the session ends.'}</p></div>`}</section></div><div class="stack"><section class="panel"><div class="panel-title"><h2>Around the table</h2><span class="pill"><i class="online-dot"></i> Live room</span></div><div class="seat-list">${Array.from({length:s.maxPlayers},(_,i)=>{const p=S.players[i];const bot=!p&&i<S.players.length+s.bots;return p?`<div class="lobby-seat"><span class="avatar">${esc(p.name[0].toUpperCase())}</span><div class="grow"><strong>${esc(p.name)}${p.id===S.you?' · you':''}</strong><small>${p.connected?'Connected':'Disconnected'}${p.id===S.hostId?' · host':''}</small></div>${!p.connected&&isHost()?button('×','remove','small ghost',`data-id="${p.id}" aria-label="Remove disconnected seat"`):''}</div>`:`<div class="lobby-seat empty"><span class="avatar">${bot?'♧':'+'}</span><div><strong>${bot?'Practice bot':'Open seat'}</strong><small>${bot?'Ready when you are':'Waiting for a friend'}</small></div></div>`;}).join('')}</div><div class="setting-summary"><div><div class="eyebrow">Starting stack</div><strong>${num(s.buyIn)}</strong><small>chips per player</small></div><div><div class="eyebrow">Blinds</div><strong>${num(s.smallBlind)} / ${num(s.bigBlind)}</strong><small>small / big blind</small></div><div><div class="eyebrow">Buy-in</div><strong>${idr(s.buyIn*s.chipValue)}</strong><small>${s.chipValue?'per player':'practice table'}</small></div></div>${isHost()?button('Start the game <span>→</span>','start','primary full arrow',S.players.length+(settingsDraft?.bots ?? s.bots)<2?'disabled':''):'<div class="notice">Waiting for the host to start. Your seat is ready.</div>'}<p class="small muted" >${S.players.length+(settingsDraft?.bots ?? s.bots)<2?'Invite at least one friend, or save a practice bot in settings.':'Starting the session records one buy-in for every player.'}</p></section><section class="panel"><div class="panel-title"><h2>A quick warm-up</h2>${button('Open guide ↗','guide','ghost small')}</div><div class="lobby-guide"><div>${cards(cs('Ah Ks'))}<h3>Two cards, just for you.</h3><p>Keep them private. Combine them with the five shared cards to make your best five-card hand.</p></div><div>${cards(cs('Th Jh Qh Kh Ah'))}<h3>Five cards make a hand.</h3><p>A royal flush is the highest hand. A simple pair can still win — or everyone else might fold.</p></div></div><div class="divider"></div><div class="notice">There’s no rush. Connected players have no action timer. Open the guide or cheat sheet whenever you need it.</div></section></div></div></section>`;}
function tableSidebar(){const g=S.game,active=!!g&&!g.over;return MejaTools.sidebar('poker',{
  connected,chat:S.chat || [],rate:S.settings.chipValue,unit:'chip',players:S.players.map(p=>({...p,score:p.stack+(active?p.contributed:0)-p.totalBuyIn})),
  log:g?.log || [],ledger:S.history,extra:S.spectator?'<section class="mk-panel"><h3>Penonton</h3><p>Kartu pribadi tetap tertutup. Antre kursi di panel Meja untuk ikut ronde berikutnya.</p></section>':g?PokerOdds.panel(currentPlayer()?.hole,g.board):'<section class="mk-panel"><h3>Contoh indikator peluang</h3><p class="mk-note">Contoh tangan A♥ K♥ + meja Q♥ J♥ 2♣, bukan kartu room ini.</p><div class="mk-cards">'+cs('Ah Kh Qh Jh 2c').map(MejaTools.card).join('')+'</div></section>'+PokerOdds.panel(cs('Ah Kh'),cs('Qh Jh 2c')),
  recapExtra:button('Full recap ↗','balances','ghost full small')+button('Buy-in ledger','ledger','ghost full small')+(S.history.length?button('Past hands','history','ghost full small'):'')+'<p class="mk-note">Net chip termasuk chip dalam pot yang belum selesai; hasil akhir setelah pot dibagikan.</p>',
  settings:S.phase==='lobby'?null:{pointValue:S.settings.chipValue,botLevel:S.settings.botLevel},host:isHost(),lobby:S.phase==='lobby',
  onChat:text=>send({type:'chat',text}),onSettings:input=>send({type:'settings',settings:{...S.settings,chipValue:input.pointValue,botLevel:input.botLevel}})
});}
function playerRole(i){const g=S.game;return [i===g.dealer?'D':'',i===g.smallBlind?'SB':'',i===g.bigBlind?'BB':''].filter(Boolean).join('/');}
function bestHand(){const me=currentPlayer();const visible=[...(me?.hole||[]),...(S?.game?.board||[])];return visible.length>=5&&visible.every(Boolean)?Poker.evaluate(visible):null;}
function seat(p,i){const g=S.game;return `<div class="player-seat ${!g.over&&g.turn===i?'active':''} ${p.folded?'folded':''}"><div class="seat-head"><span class="seat-name">${esc(p.name)}</span>${playerRole(i)?`<span class="seat-role" title="Dealer / small blind / big blind">${playerRole(i)}</span>`:''}</div>${cards(p.hole.length?p.hole:[null,null],'tiny')}<div class="chips">${num(p.stack)} <small>chips</small></div><div class="money">${idr(p.stack*S.settings.chipValue)}${p.bet?' · bet '+num(p.bet):''}</div><div class="last-action">${!p.inHand?'Sitting out':p.folded?'Folded':!p.stack&&!g.over?'All-in':esc(p.lastAction)||'In the hand'}</div>${!p.connected&&!p.bot?'<span class="seat-offline">Offline · auto check/fold</span>':''}</div>`;}
function game(){const g=S.game,me=currentPlayer(),idx=S.players.indexOf(me),host=isHost(),bh=bestHand();const mine=!g.over&&g.turn===idx;const board=Array.from({length:5},(_,i)=>g.board[i]||'blank');return `<section class="game-page"><div class="game-heading"><div><div class="eyebrow">Room ${esc(S.code)} · ${host?'You’re hosting':'Home table'}</div><h1>Let’s play a hand.</h1></div><div class="row"><span class="pill ${S.settings.chipValue?'':'practice'}">${S.settings.chipValue?'1 chip = '+idr(S.settings.chipValue):'Practice · no payments'}</span>${button('Recap ↗','balances','small')}${button('End session','end-dialog','small ghost')}${button('⎋','leave','small ghost','aria-label="Leave table"')}</div></div><div class="game-layout"><div><div class="table-shell"><div class="table-topline"><span>Texas Hold’em · no limit</span><span class="pill">Hand #${g.handNo} &nbsp; · &nbsp; Blinds ${S.settings.smallBlind}/${S.settings.bigBlind}</span></div><div class="opponents opponents-${S.players.length-1}">${S.players.map((p,i)=>p.id!==S.you?seat(p,i):'').join('')}</div><div class="community"><div class="pot"><div class="pot-label">${g.over?'Hand complete':'Total pot'}</div><div class="pot-number">${num(g.over?g.result.contestedPot:g.pot)}<small>chips</small></div><div class="pot-value">${idr((g.over?g.result.contestedPot:g.pot)*S.settings.chipValue)}</div></div>${cards(board,'',g.over?[]:bh?.cards||[])}<div class="streets">${['preflop','flop','turn','river','showdown'].map(s=>`<span class="${g.phase===s?'current':''}">${s==='preflop'?'Pre-flop':s}</span>`).join('')}</div></div><div class="turn-banner ${mine?'mine':''}"><strong>${g.over?'Hand complete':mine?'YOUR TURN':`${esc(S.players[g.turn]?.name)}’s turn`}</strong><small>${g.over?'Review the result below':mine?'Take your time.':'Waiting for a decision'}</small></div>${S.spectator?'<div class="hand-description">Kamu menonton. Antre kursi di panel Meja untuk ikut ronde berikutnya.</div>':`<div class="your-area">${cards(me.hole,'',bh?.cards||[])}<div><div class="you-label">${esc(me.name)} · YOU ${playerRole(idx)?'· '+playerRole(idx):''}</div><div class="your-chips">${num(me.stack)} <small>chips</small></div><div class="your-value">${idr(me.stack*S.settings.chipValue)}${me.contributed?' · '+num(me.contributed)+' in pot':''}</div></div></div><div class="hand-description">${me.folded?'You folded. Your remaining chips are safe for the next hand.':!me.inHand?'You’re sitting out this hand.':bh?`Your best hand: <strong>${bh.name}</strong> · highlighted in gold`:'Your two private cards · five community cards to come'}</div>`}</div>${g.over?resultPanel():actionPanel()}${g.over?rebuyPanel():''}${g.over&&host?hostBetween():''}</div>${tableSidebar()}</div></section>`;}
function coach(){if(S.spectator)return '<p>Kamu menonton. Kartu pribadi pemain tetap tertutup sampai showdown yang sah.</p>';const g=S.game,o=g.options,me=currentPlayer();let html;
  if(g.over)html='<p><strong>The hand is finished.</strong> Compare revealed hands below. Only the best five cards count; a higher kicker breaks a tie. Identical hands split the pot.</p><p>The host deals the next hand. If your chips ran out, choose whether to rebuy or sit out.</p>';
  else if(me.folded)html='<p><strong>Folding is part of poker.</strong> You’re out of this hand and keep your remaining stack. Watch the board, or browse hand rankings while the others play.</p>';
  else if(o)html=`<p><strong>${o.check?'You can check for free.':`It costs ${num(o.call)} chips (${idr(o.call*S.settings.chipValue)}) to call.`}</strong> ${o.check?'Check keeps you in without adding chips. A bet asks the others to match you.':'Call matches the current bet. Fold gives up this hand. Chips already in the pot stay there.'}</p><p>${o.canRaise?`Raise sets your <strong>total bet for this round</strong>, including your ${num(o.bet)} chips already bet. Minimum total: ${num(o.minTo)}.`:'Raising is unavailable when there is no opponent with chips to respond, or a short all-in has not reopened betting.'}</p>`;
  else html=`<p><strong>${g.phase==='preflop'?'Before the flop':g.phase==='flop'?'The flop: three shared cards':g.phase==='turn'?'The turn: the fourth shared card':'The river: the final shared card'}.</strong> ${g.phase==='preflop'?'You each have two private cards. The small and big blinds start the pot.':'Make your best five-card hand from your two cards and the board. You may use both, one, or neither private card.'}</p><p>Dealer <strong>D</strong> moves clockwise each hand. After the flop, the first active seat left of D acts first.</p>`;
  return `<div class="coach-copy">${html}</div>`;
}
function actionPanel(){if(S.spectator)return '<div class="action-panel"><p>Kamu menonton; semua aksi kartu hanya untuk pemain yang duduk.</p></div>';const g=S.game,o=g.options,me=currentPlayer();if(!o)return `<div class="action-panel"><p class="small muted">${me.stack===0&&!me.folded&&me.inHand?'You’re all-in. No more decisions this hand — you can win only the pots you contributed to.':me.folded?'You’ve folded. The next hand is a fresh start.':!me.inHand?'You are watching this hand.':'Your actions will appear here when it’s your turn.'}</p></div>`;
  return `<section class="action-panel" aria-label="Your poker actions"><div class="action-title"><strong>${o.check?'Nothing to call. You can check.':`Call ${num(o.call)} chips · ${idr(o.call*S.settings.chipValue)}`}</strong></div><div class="action-buttons">${button('Fold','fold','ghost')}${button(o.check?'Check · free':`Call ${num(o.call)}`,'check-call','primary')}${button(`All-in ${num(currentPlayer().stack)}`,'allin-dialog','gold',o.allIn?'':'disabled')}</div>${o.canRaise?`<div class="raise-controls"><label class="field" for="raise-amount">${g.currentBet?'Raise to':'Bet'} (total chips this round)<input id="raise-amount" type="number" inputmode="numeric" min="${Math.min(o.minTo,o.maxTo)}" max="${o.maxTo}" step="1" value="${Math.min(o.minTo,o.maxTo)}"></label>${button(g.currentBet?'Raise →':'Bet →','raise','primary')}<div class="raise-presets"><button data-do="preset" data-size="min">Minimum</button><button data-do="preset" data-size="half">½ pot</button><button data-do="preset" data-size="pot">Pot</button><button data-do="preset" data-size="max">All chips</button></div></div>`:''}<p class="action-help">${o.canRaise?`Minimum total ${num(o.minTo)} · Your maximum ${num(o.maxTo)}. A smaller raise is allowed only when you go all-in.`:'Check or call to stay in, or fold to leave this hand.'}</p></section>`;
}
function resultPanel(){const g=S.game,r=g.result;const winners=S.players.filter((p,i)=>r.awards[i]>0);return `<section class="result-panel"><div class="eyebrow">${r.showdown?'Showdown':'Everyone else folded'}</div><h2>${esc(winners.map(p=>p.name).join(' & '))} ${winners.length===1?'wins':'win'}.</h2><p class="small muted">${num(r.contestedPot)} chips awarded · ${idr(r.contestedPot*S.settings.chipValue)}</p>${r.pots.map((pot,k)=>`<div class="result-hand"><span>${k===0?'Main pot':'Side pot '+k} · ${num(pot.amount)} chips</span><strong>${pot.winners.map(i=>esc(S.players[i].name)).join(' + ')}${pot.winners.length>1?' · split':''}</strong></div>`).join('')}${r.showdown?S.players.map((p,i)=>r.ranks[i]?`<div class="result-hand"><div><strong>${esc(p.name)}</strong><br><span class="muted">${r.ranks[i].name} · ${r.delta[i]>=0?'+':''}${num(r.delta[i])} chips</span></div>${cards(r.ranks[i].cards,'mini')}</div>`:'').join(''):''}${r.refunds.some(n=>n>0)?`<p class="small muted">Uncalled chips returned: ${r.refunds.map((n,i)=>n?`${esc(S.players[i].name)} ${num(n)}`:'').filter(Boolean).join(', ')}.</p>`:''}${!isHost()?'<div class="divider"></div><p class="small muted">Waiting for the host to deal the next hand.</p>':''}</section>`;}
function rebuyPanel(){if(S.spectator)return "";const me=currentPlayer(),s=S.settings;let html='';if(me.stack===0){html=`<section class="rebuy-box"><h3>${me.rebuyPending?'Rebuy requested':me.rebuyDeclined?'You’re sitting out':'Out of chips. Stay for another hand?'}</h3><p>${me.rebuyPending?'Waiting for the host to approve. No chips or IDR have been added yet.':me.rebuyDeclined?'Your result stays in the recap. You can watch the table or request a rebuy between hands.':`${num(s.buyIn)} new chips cost ${idr(s.buyIn*s.chipValue)}. Your previous buy-ins stay in the ledger.`}</p><div class="row">${s.allowRebuy&&!me.rebuyPending?button('Request rebuy','rebuy-dialog','primary small'):''}${!me.rebuyDeclined?button(me.rebuyPending?'Cancel & sit out':'No thanks, sit out','sitout','ghost small'):''}</div></section>`;}
  if(isHost()){const requests=S.players.filter(p=>p.rebuyPending);if(requests.length)html+=`<section class="rebuy-box"><h3>Rebuy requests</h3>${requests.map(p=>`<div class="result-hand"><div><strong>${esc(p.name)}</strong><br><span class="muted">${num(s.buyIn)} chips · ${idr(s.buyIn*s.chipValue)}</span></div><div class="row">${button('Approve','approve','primary small',`data-id="${p.id}"`)}${button('Decline','decline','ghost small',`data-id="${p.id}"`)}</div></div>`).join('')}</section>`;}
  return html;
}
function gateText(){const gate=S.endGate;if(S.settings.playMode==='quick')return gate.handActive?'Quick Play · one hand. The session ends automatically after this hand is settled.':'Quick Play complete · one hand settled. Choose a new Quick Play explicitly to play again.';return gate.handActive?'Finish this hand before ending the session.':gate.pending?'Resolve the pending rebuy requests first.':gate.earlyFinish?'Early finish is available: only one player has chips, and everyone else has declined a rebuy.':gate.waiting.length?`Minimum play: each funded player must complete 3 turns as dealer. Still playing: ${gate.waiting.map(p=>`${esc(p.name)} (${p.rounds}/3)`).join(', ')}.`:'Three dealer rotations completed for all remaining players. The host can end the session.';}
function hostBetween(){const unresolved=S.players.some(p=>!p.bot&&p.connected&&p.stack===0&&!p.rebuyDeclined)||S.players.some(p=>p.rebuyPending);const active=S.players.filter(p=>p.stack>0&&!p.sittingOut&&(p.connected||p.bot)).length;return `<section class="action-panel"><div class="row">${button('Deal next hand →','next','primary grow',unresolved||active<2?'disabled':'')}${button('End session','end-dialog','ghost')}</div><p class="end-lock">${gateText()}</p>${active<2?'<p class="end-lock">At least two active players with chips are needed to continue. A player can rebuy or reconnect.</p>':''}${unresolved?'<p class="end-lock">Waiting for busted players to choose rebuy or sit out.</p>':''}</section>`;}
function recapTable(){const active=S.game&&!S.game.over;return `<p class="small muted mobile-scroll-hint">Swipe the table to see all balances →</p><div class="table-scroll" tabindex="0" aria-label="Scrollable table"><table class="data-table"><thead><tr><th>Player</th><th>Buy-ins</th><th>Bought chips</th><th>Total buy-in</th><th>Stack</th>${active?'<th>In pot</th>':''}<th>Stack value</th><th>${active?'Net so far*':'Net result'}</th></tr></thead><tbody>${(S.accounts||S.players).map(p=>{const net=(p.stack+(active?p.contributed:0)-p.totalBuyIn)*S.settings.chipValue;return `<tr><td><strong>${esc(p.name)}</strong><small>${S.settings.playMode==='quick'?'Quick Play · ':p.dealerRounds+'/3 dealer rounds · '}${p.handsPlayed} hands total</small></td><td>${p.buyIns}</td><td>${num(p.totalBuyIn)}</td><td>${idr(p.totalBuyIn*S.settings.chipValue)}</td><td>${num(p.stack)}</td>${active?`<td>${num(p.contributed)}</td>`:''}<td>${idr(p.stack*S.settings.chipValue)}</td><td class="${net<0?'negative':net>0?'positive':''}">${signed(net)}</td></tr>`;}).join('')}</tbody></table></div>${active?'<p class="small muted">*Net so far includes chips committed to this unfinished pot at their original value. The final result is determined after the pot is awarded.</p>':''}`;}
function ended(){const s=S.settings,total=(S.accounts||S.players).reduce((n,p)=>n+p.totalBuyIn,0);return `<section class="session-summary"><div class="summary-hero"><span class="brand-mark">♠</span><div class="eyebrow">Room ${esc(S.code)} · Session complete</div><h1>That’s a good game.</h1><p class="muted">${s.playMode==='quick'?'Quick Play complete · one hand settled. Here’s where every chip landed.':'The host closed the table. Here’s where every chip landed.'}</p></div><section class="panel"><div class="panel-title"><h2>The final tally</h2>${button('Download recap CSV ↓','export','small')}</div><div class="summary-stats"><div><span class="eyebrow">Hands played</span><b>${S.game.handNo}</b></div><div><span class="eyebrow">Chip value</span><b>${idr(s.chipValue)}</b></div><div><span class="eyebrow">Total buy-ins</span><b>${idr(total*s.chipValue)}</b></div></div>${recapTable()}</section><section class="panel stack"><div><div class="eyebrow">Settle up</div><h2>Who pays whom</h2></div>${s.chipValue&&!S.simulation?`<p class="small muted">These transfers settle the net result if buy-ins were recorded but no money has changed hands yet.</p>${S.payments.length?S.payments.map(p=>`<div class="payment-row"><strong>${esc(p.fromName)}</strong><span class="arrow">pays →</span><strong>${esc(p.toName)}</strong><b>${idr(p.amount)}</b></div>`).join(''):'<div class="notice">Everyone finished even. No transfers needed.</div>'}<div class="notice"><strong>If buy-ins were already paid into a shared bank:</strong> do not make the transfers above. The bank instead returns each player’s “Stack value” in the recap. Use one settlement method.</div>`:'<div class="notice">Chip and IDR results on this practice table are simulated. No payments are due.</div>'}<div class="row">${button('Copy settlement','copy-settlement','primary')}${button('Buy-in history','ledger','ghost')}${button('Return home','leave','ghost')}</div></section></section>`;}
function modal(title,body,actions='',eyebrow='Poker P2P'){const dlg=$('#modal');$('#modal-content').innerHTML=`<div class="modal-head"><div><div class="eyebrow">${eyebrow}</div><h2 id="modal-title">${title}</h2></div><button class="close" data-do="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}`;if(!dlg.open)dlg.showModal();}
function closeModal(){modalType=null;$('#modal').close();}
const GUIDE=[
  {title:'Two cards. One great hand.',body:`<p>You get <strong>two private cards</strong>. The table eventually gets <strong>five community cards</strong>. Make the best five-card hand from those seven cards. Use two, one, or none of your private cards.</p><div class="guide-visual"><div>${cards(cs('Ah Ks'))}<small>Your private cards</small></div><span>+</span><div>${cards(cs('Qh Jc Ts 3d 2s'))}<small>Shared by everyone</small></div></div><p>In this example, A–K–Q–J–10 makes a <strong>straight</strong>. You win by having the strongest hand at showdown, or by being the last player who hasn’t folded.</p>`},
  {title:'Follow the hand.',body:`<div class="rule-row"><b>01</b><p><strong>Pre-flop:</strong> everyone gets two cards. The players left of the dealer post the small and big blinds, then betting begins.</p></div><div class="rule-row"><b>02</b><p><strong>Flop:</strong> three community cards appear. Another betting round follows.</p></div><div class="rule-row"><b>03</b><p><strong>Turn:</strong> a fourth community card appears. Bet again.</p></div><div class="rule-row"><b>04</b><p><strong>River:</strong> the fifth and final community card appears. One last betting round.</p></div><div class="rule-row"><b>05</b><p><strong>Showdown:</strong> remaining hands are revealed and the best five cards win.</p></div><div class="notice">If everyone but one player folds, the hand ends immediately. The winner keeps their private cards hidden.</div>`},
  {title:'Your choices, explained.',body:`<div class="rule-row"><b>Check</b><p>Stay in without betting. Available only when you owe no more chips this round.</p></div><div class="rule-row"><b>Call</b><p>Match the current bet. The button shows how many additional chips you pay.</p></div><div class="rule-row"><b>Bet / raise</b><p>Increase the bet. “Raise to 40” means your total bet this round becomes 40, including chips already bet.</p></div><div class="rule-row"><b>Fold</b><p>Give up this hand. Your uncommitted chips stay with you; chips already in the pot don’t come back.</p></div><div class="rule-row"><b>All-in</b><p>Commit your remaining stack. You never need to buy more chips during a hand to stay eligible for your share of the pot.</p></div><p>A full raise must be at least as large as the last full raise. A short all-in may not reopen raising for players who already acted.</p>`},
  {title:'The little details matter.',body:`<p><strong>D = dealer, SB = small blind, BB = big blind.</strong> The dealer moves clockwise. Before the flop, the first player after the big blind acts. After the flop, the first active player left of the dealer acts.</p><p><strong>Two players?</strong> The dealer posts the small blind and acts first before the flop, but last after the flop.</p><p><strong>A tie?</strong> Compare the highest five cards, including kickers. Identical hands split the pot. Suits never break ties. An odd chip goes to the first tied winner clockwise after the dealer.</p><p><strong>Different all-in amounts?</strong> The app builds side pots automatically. You can win only the pots you contributed to. Any uncalled excess is returned.</p><p><strong>Aces</strong> can be high (10–J–Q–K–A) or low (A–2–3–4–5), but a straight cannot wrap through the ace.</p>`},
  {title:'Know your chips and IDR.',body:`<p>The host sets <strong>the value of one chip</strong>, the buy-in stack and the blinds before the game. These stay fixed throughout the session.</p><div class="notice"><strong>Example</strong><br>1 chip = Rp100<br>Buy 1,000 chips → Rp100,000 recorded buy-in<br>Finish with 1,250 chips → Rp125,000 stack value<br>Net result → +Rp25,000</div><p>If you lose your stack, request a <strong>rebuy between hands</strong>. Chips and the cost are recorded only after host approval. You can also decline and watch.</p><p>Practice bots use the chosen chip value for simulated IDR results. Tables with bots do not create payment instructions.</p>`},
  {title:'A fair finish for everyone.',body:`<p>Each funded player must complete <strong>three turns as dealer</strong> before the host can end the session. The recap tracks everyone’s progress. Busted players who decline a rebuy are exempt from the remaining rotations.</p><p><strong>Early finish:</strong> if only one player has chips and everyone else declines a rebuy, the host can confirm the final result immediately.</p><p>The host can end only <strong>between hands</strong>, after all pending rebuys are resolved, and must confirm the final action.</p><p>The final result shows chips, all buy-ins, net IDR results and <strong>who pays whom</strong>. If money was already collected in a shared bank, use the stack values as bank payouts instead.</p><p>On a dropped connection, reopen the same address in the same browser to return to your seat. Offline turns check if possible, otherwise fold after 15 seconds. No automated call spends a disconnected player’s stack.</p><div class="notice">You’re ready. Take your time, and keep the cheat sheet nearby.</div>`}
];
function showGuide(){modalType='guide';const step=GUIDE[guideStep];modal(step.title,`<div class="guide-stepbar">${GUIDE.map((_,i)=>`<span class="${i<=guideStep?'on':''}"></span>`).join('')}</div>${step.body}<div class="guide-nav">${button('← Back','guide-back','ghost small',guideStep===0?'disabled':'')}<span>${guideStep+1} of ${GUIDE.length}</span>${button(guideStep===GUIDE.length-1?'Ready to play':'Next →',guideStep===GUIDE.length-1?'close':'guide-next','primary small')}</div>`,'','A beginner’s guide');}
const RANKINGS=[['Royal flush','A, K, Q, J, 10 of one suit','Ah Kh Qh Jh Th'],['Straight flush','Five in sequence, one suit','9s 8s 7s 6s 5s'],['Four of a kind','Four cards of one rank','Qc Qd Qh Qs 2h'],['Full house','Three of a kind + a pair','Kh Kd Ks 4h 4c'],['Flush','Five of one suit','Ac Jc 8c 6c 3c'],['Straight','Five ranks in sequence','9h 8d 7s 6c 5h'],['Three of a kind','Three cards of one rank','7s 7h 7d Kc 2s'],['Two pair','Two different pairs','Jh Jd 4s 4h Ac'],['One pair','Two cards of one rank','8c 8h As Qd 3s'],['High card','None of the combinations above','As Jd 8c 6h 2s']];
function showCheat(){modalType='cheat';modal('The hand rankings.',`<p>Strongest at the top. Compare your best five cards; a higher kicker breaks ties.</p>${RANKINGS.map((r,i)=>`<div class="rank-row"><span class="rank-num">${String(i+1).padStart(2,'0')}</span><div><strong>${r[0]}</strong><p>${r[1]}</p></div>${cards(cs(r[2]))}</div>`).join('')}<div class="notice">Same five-card strength? Split the pot. Suits have equal value. A–2–3–4–5 is the lowest straight.</div>`,'','Keep this close');}
function showBalances(){modalType='balances';modal('Every chip accounted for.',`<p>Room ${esc(S.code)} · 1 chip = ${idr(S.settings.chipValue)} · Blinds ${S.settings.smallBlind}/${S.settings.bigBlind}</p>${recapTable()}<p>${gateText()}</p>`,button('Buy-in history','ledger','ghost small')+button('Download CSV ↓','export','primary small'),'Live table recap');}
function showLedger(){modalType='ledger';modal('The buy-in ledger.',`<p>Only approved buy-ins are included. Rebuy requests do not change balances until the host approves.</p><div class="table-scroll" tabindex="0" aria-label="Scrollable table"><table class="data-table"><thead><tr><th>Player / time</th><th>Type</th><th>Chips</th><th>IDR</th></tr></thead><tbody>${S.ledger.map(l=>`<tr><td>${esc(l.name)}<small>${new Date(l.time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</small></td><td>${esc(l.kind)}</td><td>${num(l.chips)}</td><td>${idr(l.idr)}</td></tr>`).join('')}</tbody></table></div>`,button('Back to recap','balances','ghost small'));}
function endDialog(){modalType='end';const gate=S.endGate;modal(gate.allowed?'Call it a night?':'A little more play first.',`<p>${gateText()}</p><div class="progress-rows">${S.players.map(p=>`<span class="pill">${esc(p.name)} · ${S.settings.playMode==='quick'?p.handsPlayed+' hands':p.dealerRounds+'/3'}${!p.stack&&p.rebuyDeclined?' · sitting out':''}</span>`).join('')}</div>${gate.allowed?'<p>Ending closes the session for everyone. The final chip balances, IDR results, and settlement instructions will be saved. No more hands or rebuys can be added.</p>':'<p>The host can finish only between hands, after everyone’s minimum play and pending rebuy decisions are complete.</p>'}${!isHost()?'<p><strong>Only the host can end the session.</strong></p>':''}`,button('Keep playing','close','ghost')+(gate.allowed&&isHost()?button('Confirm & end session','confirm-end','danger'):''));}
function settlementText(){const s=S.settings;if(S.simulation)return `Poker P2P · Room ${S.code}\nSimulated chip/IDR recap with bots. No payment instructions.\n${(S.accounts||S.players).map(p=>p.name+': '+signed((p.stack-p.totalBuyIn)*s.chipValue)).join('\n')}`;if(!s.chipValue)return `Poker P2P · Room ${S.code}\nPractice session. No payments due.`;return `Poker P2P · Room ${S.code}\n1 chip = ${idr(s.chipValue)}\n\nNet transfers (if no money has changed hands):\n${S.payments.map(p=>`${p.fromName} pays ${p.toName}: ${idr(p.amount)}`).join('\n')||'No transfers needed.'}\n\nIf buy-ins were already paid into a bank, use these bank payouts instead:\n${(S.accounts||S.players).map(p=>`${p.name}: ${idr(p.stack*s.chipValue)}`).join('\n')}\n\nUse only one settlement method.`;}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied.');}catch{const area=document.createElement('textarea');area.value=text;document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();toast(ok?'Copied.':'Copy is unavailable in this browser. Select the text shown in the room.');}}
function exportCSV(){const active=!S.game?.over;const rows=[['Poker P2P session',S.code],['Status',S.phase],['IDR per chip',S.settings.chipValue],[],['Player','Buy-ins','Bought chips','Total buy-in IDR','Remaining chips','Chips in active pot','Stack value IDR','Net including unsettled chips IDR','Hands played','Dealer rounds'],...(S.accounts||S.players).map(p=>[p.name,p.buyIns,p.totalBuyIn,p.totalBuyIn*S.settings.chipValue,p.stack,active?p.contributed:0,p.stack*S.settings.chipValue,(p.stack+(active?p.contributed:0)-p.totalBuyIn)*S.settings.chipValue,p.handsPlayed,p.dealerRounds]),[],['Approved buy-in ledger'],['Player','Type','Chips','IDR','Time'],...S.ledger.map(l=>[l.name,l.kind,l.chips,l.idr,new Date(l.time).toISOString()])];if(S.phase==='ended'&&S.settings.chipValue&&!S.simulation)rows.push([],['Net transfers only if buy-ins were NOT paid into a bank'],['From','To','IDR'],...S.payments.map(p=>[p.fromName,p.toName,p.amount]),[],['If buy-ins were paid into a bank use stack value payouts instead. Do not use both methods.']);if(active)rows.push([],['Unfinished pot: net amounts include committed chips at original value and are not final.']);const cell=x=>{let v=String(x??'');if(typeof x==='string'&&/^[=+@\-\t\r]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"';};const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`poker-${S.code}-recap.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function savePokerSettings(){if(!settingsDraft||S?.phase!=='lobby'||!isHost())return;const f=$('#settings-form');if(!f||!f.checkValidity())return;if(pending){settingsTimer=setTimeout(savePokerSettings,300);return;}const s=readSettings();if(s.bigBlind<s.smallBlind*2||s.buyIn<s.bigBlind*20||s.bots>=s.maxPlayers||S.players.length+s.bots>s.maxPlayers)return;send({type:'settings',settings:s});}
function readSettings(){const f=$('#settings-form');return {chipValue:Number(f.elements.chipValue.value),buyIn:Number(f.elements.buyIn.value),smallBlind:Number(f.elements.smallBlind.value),bigBlind:Number(f.elements.bigBlind.value),maxPlayers:Number(f.elements.maxPlayers.value),bots:Number(f.elements.bots.value),botLevel:f.elements.botLevel.value,playMode:f.elements.playMode.value,allowRebuy:f.elements.allowRebuy.checked};}
function act(action,amount){if(send({type:'action',action,amount,version:S.game.version})){closeModal();render();}}
function doAction(action,el){
  if(['create','join'].includes(action)){const name=$('#player-name').value.trim();if(!name){$('#player-name').reportValidity();return;}enteredName=name;safeSet(localStorage,'mejakita.poker.name',name);if(action==='create')send({type:'create',name});else{enteredCode=$('#join-code').value.trim().toUpperCase();if(!/^[A-Z]{4}$/.test(enteredCode)){toast('Enter the four-letter room code.');return;}send({type:'join',name,code:enteredCode});}return;}
  if(action==='resume'){if(saved)send({type:'resume',...saved});return;}

  if(action==='close'){closeModal();return;}
  if(action==='guide'){guideStep=0;showGuide();return;}
  if(action==='guide-next'){guideStep=Math.min(GUIDE.length-1,guideStep+1);showGuide();return;}
  if(action==='guide-back'){guideStep=Math.max(0,guideStep-1);showGuide();return;}
  if(action==='cheat'){showCheat();return;}
  if(!S)return;
  if(action==='copy-code')return copy(S.code);
  if(action==='copy-link')return copy(shareLink());
  if(action==='balances')return showBalances();
  if(action==='ledger')return showLedger();
  if(action==='export')return exportCSV();
  if(action==='copy-settlement')return copy(settlementText());
  if(action==='end-dialog')return endDialog();
  if(action==='confirm-end'){if(send({type:'end',confirm:true}))closeModal();return;}
  if(action==='start'){clearTimeout(settingsTimer);send({type:'start',settings:readSettings()});settingsDraft=null;return;}
  if(action==='next'){send({type:'next'});return;}
  if(action==='remove'){send({type:'remove',id:el.dataset.id});return;}
  if(action==='sitout'){send({type:'sitout'});return;}
  if(action==='approve'||action==='decline'){send({type:'rebuyDecision',id:el.dataset.id,approve:action==='approve'});return;}
  if(action==='rebuy-dialog'){modalType='rebuy';modal('Buy back in?',`<p>Request <strong>${num(S.settings.buyIn)} chips</strong> for <strong>${idr(S.settings.buyIn*S.settings.chipValue)}</strong>.</p><p>The host needs to approve. Once approved, this amount is added to your total buy-ins and final result.</p>`,button('Cancel','close','ghost')+button('Request rebuy','confirm-rebuy','primary'));return;}
  if(action==='confirm-rebuy'){if(send({type:'rebuy'}))closeModal();return;}
  if(action==='check-call'){act(S.game.options.check?'check':'call');return;}
  if(action==='fold'){act('fold');return;}
  if(action==='allin-dialog'){modalType='allin';modal('Put your stack in?',`<p>Commit your remaining <strong>${num(currentPlayer().stack)} chips</strong> (${idr(currentPlayer().stack*S.settings.chipValue)}) to this hand.</p><p>You can still win the pots you contribute to, even if another player bets more.</p>`,button('Cancel','close','ghost')+button('Confirm all-in','confirm-allin','gold'));return;}
  if(action==='confirm-allin'){act('allin');return;}
  if(action==='raise'){const amount=Number($('#raise-amount').value),o=S.game.options;if(!Number.isSafeInteger(amount)||amount>o.maxTo||amount<o.minTo&&amount!==o.maxTo){toast(`Choose at least ${num(o.minTo)}, or all ${num(o.maxTo)} chips.`);return;}if(amount===o.maxTo)return doAction('allin-dialog');act('raise',amount);return;}
  if(action==='preset'){const o=S.game.options;const amount=el.dataset.size==='min'?o.minTo:el.dataset.size==='max'?o.maxTo:S.game.currentBet+Math.max(S.settings.bigBlind,Math.floor((S.game.pot+o.call)*(el.dataset.size==='half'?.5:1)));$('#raise-amount').value=Math.min(o.maxTo,Math.max(o.minTo,amount));return;}
  if(action==='history'){modalType='history';modal('Previous hands.',S.history.slice().reverse().map(h=>`<div class="result-hand"><div><strong>Hand #${h.handNo}</strong><br><span class="muted">${h.result.awards.map((n,i)=>n?esc(h.names[i])+': '+num(n)+' chips':'').filter(Boolean).join(' · ')}</span></div>${h.board.length?cards(h.board,'mini'):'<span class="muted small">Won before the board</span>'}</div>`).join(''),'','Last 20 completed hands');return;}
  if(action==='leave'){if(S.phase==='ended'){send({type:'leave'});return;}modalType='leave';modal('Leave the table?',`<p>${S.phase==='lobby'?'Your seat will be removed from the waiting room.':'Your stack and buy-ins stay in the recap. Any active hand will check or fold while you are away. Use “Return to saved room” to reconnect.'}</p>`,button('Stay','close','primary')+button('Leave table','confirm-leave','ghost'));return;}
  if(action==='confirm-leave'){send({type:'leave'});closeModal();}
}
document.addEventListener('click',event=>{const el=event.target.closest('[data-do]');if(!el||el.disabled)return;event.preventDefault();doAction(el.dataset.do,el);});
document.addEventListener('submit',event=>{event.preventDefault();if(event.target.id==='create-form')doAction('create');else if(event.target.id==='join-form')doAction('join');else if(event.target.id==='settings-form'){const settings=readSettings();settingsDraft=null;send({type:'settings',settings});}});
document.addEventListener('input',event=>{if(event.target.id==='player-name')enteredName=event.target.value;if(event.target.id==='join-code')enteredCode=event.target.value;if(event.target.closest('#settings-form')){settingsDraft=readSettings();if($('#play-mode-note'))$('#play-mode-note').textContent=playModeCopy(settingsDraft);$('#chip-value').disabled=false;$('#settings-cost').textContent=idr(settingsDraft.buyIn*settingsDraft.chipValue);$('#practice-note').textContent=`${num(settingsDraft.buyIn)} chips × ${idr(settingsDraft.chipValue)} · nilai simulasi`;clearTimeout(settingsTimer);settingsTimer=setTimeout(savePokerSettings,650);}});
document.addEventListener('change',event=>{if(event.target.closest('#settings-form')){settingsDraft=readSettings();if($('#play-mode-note'))$('#play-mode-note').textContent=playModeCopy(settingsDraft);clearTimeout(settingsTimer);settingsTimer=setTimeout(savePokerSettings,150);} if(event.target.id==='beginner-toggle'){beginner=event.target.checked;safeSet(localStorage,'mejakita.poker.beginner',String(beginner));render();}if(event.target.id==='share-address'){selectedAddress=event.target.value;render();}});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
$('#modal').addEventListener('cancel',()=>modalType=null);
fetch('/poker/api/info').then(r=>r.json()).then(data=>{info=data;if(!S||S.phase==='lobby')render();}).catch(()=>{});
render();connect();
